function _decodeZoneRle(b64, total) {
  const bin = atob(b64);
  const out = new Uint8Array(total);
  let p = 0, k = 0;
  while (p < bin.length) {
    const tier = bin.charCodeAt(p++);
    let run = 0, shift = 0, c;
    do {
      c = bin.charCodeAt(p++);
      run |= (c & 0x7F) << shift;
      shift += 7;
    } while (c & 0x80);
    out.fill(tier, k, k + run);
    k += run;
  }
  return out;
}
const _zoneTiers = _decodeZoneRle(ZONE_RLE_B64, GRID_W * GRID_H);

/** Rarity tier (0-13) of the zone covering tile (gx, gy); -1 if off the grid or a wall. */
export function getZoneTierAtTile(gx, gy) {
  if (!isOpenTile(gx, gy)) return -1;
  return _zoneTiers[gy * GRID_W + gx];
}

/** Rarity tier (0-13) of the zone at a world position; -1 if off the grid or in a wall. */
export function getZoneTierAt(x, y) {
  return getZoneTierAtTile(Math.floor(x / TILE_SIZE), Math.floor(y / TILE_SIZE));
}

