const DIST_GRID_STEP = 4;
const DIST_GRID_W = Math.ceil(GRID_W / DIST_GRID_STEP);
const DIST_GRID_H = Math.ceil(GRID_H / DIST_GRID_STEP);

function _base64ToUint16Array(b64) {
  const binStr = atob(b64);
  const bytes = new Uint8Array(binStr.length);
  for (let i = 0; i < binStr.length; i++) bytes[i] = binStr.charCodeAt(i);
  const out = new Uint16Array(bytes.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = bytes[i * 2] | (bytes[i * 2 + 1] << 8);
  }
  return out;
}
const _distGrid = _base64ToUint16Array(DIST_GRID_B64);

/**
 * Approximate real tunnel-distance (in tiles) from spawn to world position
 * (x, y), via a downsampled (every 4th tile) precomputed BFS flood-fill —
 * see shared/biomes/garden.js's own getDistanceFromSpawn for the full accuracy/size
 * tradeoff notes (same approach, same ~6-tile-unit margin, always rounds
 * slightly UP so it never under-credits a player's progress).
 */
export function getDistanceFromSpawn(x, y) {
  const gx = Math.floor(x / TILE_SIZE);
  const gy = Math.floor(y / TILE_SIZE);
  const dgx = Math.min(DIST_GRID_W - 1, Math.max(0, Math.floor(gx / DIST_GRID_STEP)));
  const dgy = Math.min(DIST_GRID_H - 1, Math.max(0, Math.floor(gy / DIST_GRID_STEP)));
  const v = _distGrid[dgy * DIST_GRID_W + dgx];
  return v === 0xFFFF ? -1 : v;
}

